# ==========================================
# DATABASE MANAGER
# ==========================================
class DatabaseManager:
    """Handles all SQLite database operations for the bot."""

    def __init__(self, db_path: str):
        self.db_path = db_path
        self._init_db()

    def _get_connection(self):
        conn = sqlite3.connect(self.db_path)
        conn.row_factory = sqlite3.Row
        return conn

    def _init_db(self):
        with self._get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS users (
                    user_id INTEGER PRIMARY KEY,
                    username TEXT,
                    first_name TEXT,
                    last_name TEXT,
                    joined_at TIMESTAMP,
                    is_banned BOOLEAN DEFAULT 0,
                    language TEXT DEFAULT 'en',
                    wallet_balance REAL DEFAULT 0.0,
                    xp INTEGER DEFAULT 0,
                    level INTEGER DEFAULT 1
                )
            ''')
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS profiles (
                    user_id INTEGER PRIMARY KEY,
                    name TEXT,
                    age INTEGER,
                    gender TEXT,
                    location TEXT,
                    bio TEXT,
                    photo_id TEXT,
                    FOREIGN KEY(user_id) REFERENCES users(user_id)
                )
            ''')
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS messages_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id INTEGER,
                    message_id INTEGER,
                    chat_id INTEGER,
                    text TEXT,
                    date TIMESTAMP,
                    FOREIGN KEY(user_id) REFERENCES users(user_id)
                )
            ''')
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS feedbacks (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id INTEGER,
                    text TEXT,
                    status TEXT DEFAULT 'pending',
                    created_at TIMESTAMP
                )
            ''')
            conn.commit()
            logger.info("Database initialized successfully.")

    def add_user(self, user_id: int, username: str, first_name: str, last_name: str):
        with self._get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute('''
                INSERT OR IGNORE INTO users (user_id, username, first_name, last_name, joined_at)
                VALUES (?, ?, ?, ?, ?)
            ''', (user_id, username, first_name, last_name, datetime.now()))
            conn.commit()

    def get_user(self, user_id: int) -> Optional[sqlite3.Row]:
        with self._get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute('SELECT * FROM users WHERE user_id = ?', (user_id,))
            return cursor.fetchone()

    def get_all_users(self) -> List[sqlite3.Row]:
        with self._get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute('SELECT * FROM users')
            return cursor.fetchall()

    def count_users(self) -> int:
        with self._get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute('SELECT COUNT(*) FROM users')
            return cursor.fetchone()[0]

    def set_ban_status(self, user_id: int, is_banned: bool):
        with self._get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute('UPDATE users SET is_banned = ? WHERE user_id = ?', (is_banned, user_id))
            conn.commit()

    def save_profile(self, user_id: int, profile_data: dict):
        with self._get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute('''
                INSERT OR REPLACE INTO profiles (user_id, name, age, gender, location, bio, photo_id)
                VALUES (?, ?, ?, ?, ?, ?, ?)
            ''', (
                user_id,
                profile_data.get('name'),
                profile_data.get('age'),
                profile_data.get('gender'),
                profile_data.get('location'),
                profile_data.get('bio'),
                profile_data.get('photo_id')
            ))
            conn.commit()

    def get_profile(self, user_id: int) -> Optional[sqlite3.Row]:
        with self._get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute('SELECT * FROM profiles WHERE user_id = ?', (user_id,))
            return cursor.fetchone()

    def log_message(self, user_id: int, message_id: int, chat_id: int, text: str):
        with self._get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute('''
                INSERT INTO messages_log (user_id, message_id, chat_id, text, date)
                VALUES (?, ?, ?, ?, ?)
            ''', (user_id, message_id, chat_id, text, datetime.now()))
            conn.commit()

    def save_feedback(self, user_id: int, text: str):
        with self._get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute('''
                INSERT INTO feedbacks (user_id, text, created_at)
                VALUES (?, ?, ?)
            ''', (user_id, text, datetime.now()))
            conn.commit()

db = DatabaseManager(DB_PATH)

# ==========================================
# MIDDLEWARES / DECORATORS
# ==========================================
def admin_only(func):
    """Decorator to restrict handlers to admins only."""
    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):
        user_id = update.effective_user.id
        if user_id not in ADMIN_IDS:
            await update.message.reply_text("⛔ You are not authorized to use this command.")
            return
        return await func(update, context)
    return wrapper

async def track_user_middleware(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Middleware to automatically add users to DB and log messages."""
    if not update.effective_user or not update.effective_message:
        return

    user = update.effective_user
    db.add_user(user.id, user.username, user.first_name, user.last_name)

    user_db = db.get_user(user.id)
    if user_db and user_db['is_banned']:
        if update.effective_message.text:
            await update.effective_message.reply_text("🚫 You are banned from using this bot.")
        return

    if update.effective_message.text:
        db.log_message(user.id, update.effective_message.message_id, update.effective_chat.id, update.effective_message.text)

# ==========================================
# GENERAL COMMAND HANDLERS
# ==========================================
async def start_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handler for /start command."""
    user = update.effective_user
    db.add_user(user.id, user.username, user.first_name, user.last_name)

    keyboard = [
        [InlineKeyboardButton("Register Profile", callback_data="cmd_register")],
        [InlineKeyboardButton("View Profile", callback_data="cmd_profile")],
        [InlineKeyboardButton("Help & Support", callback_data="cmd_help"), InlineKeyboardButton("Settings", callback_data="cmd_settings")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    welcome_msg = (
        f"Hello {user.first_name}! 👋\n\n"
        f"Welcome to the MegaBot. I am a fully featured, robust Telegram bot designed to demonstrate "
        f"advanced capabilities using python-telegram-bot.\n\n"
        f"Use the buttons below to navigate."
    )

    if update.message:
        await update.message.reply_text(welcome_msg, reply_markup=reply_markup)
    elif update.callback_query:
        await update.callback_query.edit_message_text(welcome_msg, reply_markup=reply_markup)

async def help_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handler for /help command."""
    help_text = (
        "📚 *MegaBot Help Menu*\n\n"
        "Here are the available commands:\n"
        "▫️ /start - Restart the bot\n"
        "▫️ /help - Show this message\n"
        "▫️ /register - Create your profile\n"
        "▫️ /profile - View your profile\n"
        "▫️ /feedback - Send feedback to admins\n"
        "▫️ /cancel - Cancel any ongoing operation\n\n"
        "*Admin Commands:*\n"
        "▫️ /admin - Open admin panel\n"
        "▫️ /stats - View bot statistics\n"
        "▫️ /broadcast - Send message to all users\n"
    )
    if update.message:
        await update.message.reply_text(help_text, parse_mode=ParseMode.MARKDOWN)
    elif update.callback_query:
        await update.callback_query.edit_message_text(help_text, parse_mode=ParseMode.MARKDOWN)

# ==========================================
# REGISTRATION CONVERSATION (FSM)
# ==========================================
async def register_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if query:
        await query.answer()
        await query.edit_message_text("Let's start your registration! 📝\n\nFirst, please enter your *Full Name*:", parse_mode=ParseMode.MARKDOWN)
    else:
        await update.message.reply_text("Let's start your registration! 📝\n\nFirst, please enter your *Full Name*:", parse_mode=ParseMode.MARKDOWN)
    return REGISTER_NAME

async def register_name(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = update.message.text
    if len(text) < 2 or len(text) > 50:
        await update.message.reply_text("Name must be between 2 and 50 characters. Try again:")
        return REGISTER_NAME
    context.user_data['reg_name'] = text
    await update.message.reply_text(f"Nice to meet you, {text}!\n\nNow, please enter your *Age* (numeric value):", parse_mode=ParseMode.MARKDOWN)
    return REGISTER_AGE

async def register_age(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = update.message.text
    if not text.isdigit() or not (10 <= int(text) <= 100):
        await update.message.reply_text("Please enter a valid age between 10 and 100:")
        return REGISTER_AGE
    context.user_data['reg_age'] = int(text)

    keyboard = [["Male", "Female", "Other"]]
    reply_markup = ReplyKeyboardMarkup(keyboard, one_time_keyboard=True, resize_keyboard=True)
    await update.message.reply_text("Got it. What is your *Gender*?", reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
    return REGISTER_GENDER

async def register_gender(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = update.message.text
    if text not in ["Male", "Female", "Other"]:
        await update.message.reply_text("Please use the keyboard to select your gender.")
        return REGISTER_GENDER
    context.user_data['reg_gender'] = text
    await update.message.reply_text("Great! Where are you from? (Enter your *City/Country*)", reply_markup=ReplyKeyboardRemove(), parse_mode=ParseMode.MARKDOWN)
    return REGISTER_LOCATION

async def register_location(update: Update, context: ContextTypes.DEFAULT_TYPE):
    context.user_data['reg_location'] = update.message.text
    await update.message.reply_text("Please write a short *Bio* about yourself:", parse_mode=ParseMode.MARKDOWN)
    return REGISTER_BIO

async def register_bio(update: Update, context: ContextTypes.DEFAULT_TYPE):
    context.user_data['reg_bio'] = update.message.text
    await update.message.reply_text("Almost done! Finally, please send a *Photo* of yourself. (Or send /skip to skip this step)", parse_mode=ParseMode.MARKDOWN)
    return REGISTER_PHOTO

async def register_photo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if update.message.photo:
        photo_id = update.message.photo[-1].file_id
        context.user_data['reg_photo'] = photo_id
    else:
        await update.message.reply_text("Please send a valid photo, or send /skip.")
        return REGISTER_PHOTO
    return await send_registration_summary(update, context)

async def register_skip_photo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    context.user_data['reg_photo'] = None
    return await send_registration_summary(update, context)

async def send_registration_summary(update: Update, context: ContextTypes.DEFAULT_TYPE):
    ud = context.user_data
    summary = (
        f"📋 *Registration Summary*\n\n"
        f"👤 *Name:* {ud.get('reg_name')}\n"
        f"🎂 *Age:* {ud.get('reg_age')}\n"
        f"⚧ *Gender:* {ud.get('reg_gender')}\n"
        f"🌍 *Location:* {ud.get('reg_location')}\n"
        f"📜 *Bio:* {ud.get('reg_bio')}\n"
    )

    keyboard = [
        [InlineKeyboardButton("✅ Confirm & Save", callback_data="reg_confirm")],
        [InlineKeyboardButton("❌ Cancel", callback_data="reg_cancel")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    if ud.get('reg_photo'):
        await update.message.reply_photo(photo=ud['reg_photo'], caption=summary, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
    else:
        await update.message.reply_text(summary, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
    return REGISTER_CONFIRM

async def register_confirm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()

    if query.data == "reg_confirm":
        ud = context.user_data
        profile_data = {
            'name': ud.get('reg_name'),
            'age': ud.get('reg_age'),
            'gender': ud.get('reg_gender'),
            'location': ud.get('reg_location'),
            'bio': ud.get('reg_bio'),
            'photo_id': ud.get('reg_photo')
        }
        db.save_profile(update.effective_user.id, profile_data)

        await query.edit_message_caption(caption="✅ Your profile has been saved successfully!") if query.message.photo else await query.edit_message_text(text="✅ Your profile has been saved successfully!")
        await asyncio.sleep(1)
        await start_command(update, context)

    elif query.data == "reg_cancel":
        if query.message.photo:
            await query.edit_message_caption(caption="❌ Registration cancelled.")
        else:
            await query.edit_message_text("❌ Registration cancelled.")

    context.user_data.clear()
    return ConversationHandler.END

async def cancel_conversation(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await update.message.reply_text("Operation cancelled.", reply_markup=ReplyKeyboardRemove())
    context.user_data.clear()
    return ConversationHandler.END

# ==========================================
# PROFILE & USER COMMANDS
# ==========================================
async def view_profile(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    user_id = update.effective_user.id

    if query:
        await query.answer()

    profile = db.get_profile(user_id)
    if not profile:
        msg = "You haven't created a profile yet. Use /register to create one."
        if query:
            await query.edit_message_text(msg)
        else:
            await update.message.reply_text(msg)
        return

    text = (
        f"👤 *Your Profile*\n\n"
        f"📛 *Name:* {profile['name']}\n"
        f"🎂 *Age:* {profile['age']}\n"
        f"⚧ *Gender:* {profile['gender']}\n"
        f"🌍 *Location:* {profile['location']}\n"
        f"📜 *Bio:* {profile['bio']}\n"
    )

    keyboard = [[InlineKeyboardButton("🔙 Back to Main Menu", callback_data="cmd_start")]]
    reply_markup = InlineKeyboardMarkup(keyboard)

    if profile['photo_id']:
        if query:
            await query.message.reply_photo(photo=profile['photo_id'], caption=text, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
            await query.message.delete()
        else:
            await update.message.reply_photo(photo=profile['photo_id'], caption=text, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
    else:
        if query:
            await query.edit_message_text(text, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
        else:
            await update.message.reply_text(text, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)

# ==========================================
# FEEDBACK SYSTEM
# ==========================================
async def feedback_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await update.message.reply_text("Please type your feedback/bug report below. Send /cancel to abort.")
    return FEEDBACK_STATE

async def feedback_receive(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = update.message.text
    user_id = update.effective_user.id
    db.save_feedback(user_id, text)

    for admin_id in ADMIN_IDS:
        try:
            await context.bot.send_message(
                chat_id=admin_id,
                text=f"🔔 *New Feedback* from [{update.effective_user.first_name}](tg://user?id={user_id}):\n\n{text}",
                parse_mode=ParseMode.MARKDOWN
            )
        except Exception as e:
            logger.error(f"Failed to notify admin {admin_id}: {e}")

    await update.message.reply_text("✅ Thank you! Your feedback has been sent to the administrators.")
    return ConversationHandler.END

# ==========================================
# ADMIN PANEL & BROADCAST
# ==========================================
@admin_only
async def admin_panel(update: Update, context: ContextTypes.DEFAULT_TYPE):
    keyboard = [
        [InlineKeyboardButton("📊 Statistics", callback_data="admin_stats")],
        [InlineKeyboardButton("📢 Broadcast", callback_data="admin_broadcast_init")],
        [InlineKeyboardButton("👥 Manage Users", callback_data="admin_users")],
        [InlineKeyboardButton("🔙 Exit Admin Panel", callback_data="cmd_start")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    text = "🛡️ *Admin Control Panel*\n\nSelect an option below:"

    if update.callback_query:
        await update.callback_query.answer()
        await update.callback_query.edit_message_text(text, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
    else:
        await update.message.reply_text(text, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)

async def admin_stats(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()

    total_users = db.count_users()
    with db._get_connection() as conn:
        cursor = conn.cursor()
        cursor.execute("SELECT COUNT(*) FROM profiles")
        total_profiles = cursor.fetchone()[0]
        cursor.execute("SELECT COUNT(*) FROM messages_log")
        total_msgs = cursor.fetchone()[0]
        cursor.execute("SELECT COUNT(*) FROM feedbacks")
        total_feedback = cursor.fetchone()[0]

    stats_text = (
        "📊 *Bot Statistics*\n\n"
        f"👥 *Total Users:* {total_users}\n"
        f"📝 *Profiles Created:* {total_profiles}\n"
        f"💬 *Messages Logged:* {total_msgs}\n"
        f"📨 *Feedback Received:* {total_feedback}\n"
    )

    keyboard = [[InlineKeyboardButton("🔙 Back", callback_data="cmd_admin")]]
    await query.edit_message_text(stats_text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.MARKDOWN)

async def admin_broadcast_init(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    await query.edit_message_text("📢 Send the message you want to broadcast to all users.\n\nSend /cancel to abort.")
    return ADMIN_BROADCAST

async def admin_broadcast_send(update: Update, context: ContextTypes.DEFAULT_TYPE):
    message = update.message
    users = db.get_all_users()

    await message.reply_text(f"⏳ Broadcasting message to {len(users)} users...")

    successful = 0
    failed = 0
    for user in users:
        try:
            await message.copy(chat_id=user['user_id'])
            successful += 1
            await asyncio.sleep(0.05)
        except Exception as e:
            logger.error(f"Failed to send broadcast to {user['user_id']}: {e}")
            failed += 1

    await message.reply_text(f"✅ Broadcast complete!\n\n✔️ Successful: {successful}\n❌ Failed: {failed}")
    return ConversationHandler.END

# ==========================================
# INLINE QUERIES
# ==========================================
async def inline_query_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.inline_query.query
    if not query:
        return

    results = [
        telegram.InlineQueryResultArticle(
            id=str(1),
            title="Search User Profiles",
            description=f"Search for '{query}' in profiles",
            input_message_content=telegram.InputTextMessageContent(
                message_text=f"Searching for profiles matching: *{query}*",
                parse_mode=ParseMode.MARKDOWN
            )
        ),
        telegram.InlineQueryResultArticle(
            id=str(2),
            title="Bot Info",
            description="Display bot information",
            input_message_content=telegram.InputTextMessageContent(
                message_text="🤖 *MegaBot*\nVersion: 1.0.0\nA demonstration of python-telegram-bot capabilities.",
                parse_mode=ParseMode.MARKDOWN
            )
        )
    ]
    await update.inline_query.answer(results, cache_time=10)

# ==========================================
# MEDIA & MISC HANDLERS
# ==========================================
async def handle_photo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await update.message.reply_text("📸 Nice photo! I have logged it in my system.")

async def handle_voice(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await update.message.reply_text("🎤 I received your voice message, but I don't know how to transcribe yet!")

async def handle_document(update: Update, context: ContextTypes.DEFAULT_TYPE):
    doc = update.message.document
    await update.message.reply_text(f"📄 Document received: {doc.file_name} ({doc.file_size} bytes)")

async def unknown_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await update.message.reply_text("Sorry, I didn't understand that command. Use /help to see available commands.")

# ==========================================
# CALLBACK ROUTER
# ==========================================
async def callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    data = query.data

    if data == "cmd_start":
        await start_command(update, context)
    elif data == "cmd_help":
        await help_command(update, context)
    elif data == "cmd_register":
        await query.answer("Use /register to start.", show_alert=True)
    elif data == "cmd_profile":
        await view_profile(update, context)
    elif data == "cmd_settings":
        await query.answer("Settings are not implemented yet in this demo.", show_alert=True)
    elif data == "cmd_admin":
        await admin_panel(update, context)
    elif data == "admin_users":
        await query.answer("User management interface not implemented in demo.", show_alert=True)
    else:
        await query.answer()

# ==========================================
# ERROR HANDLER
# ==========================================
async def error_handler(update: object, context: ContextTypes.DEFAULT_TYPE):
    logger.error("Exception while handling an update:", exc_info=context.error)
    if isinstance(update, Update) and update.effective_message:
        try:
            await update.effective_message.reply_text("⚠️ An unexpected error occurred. The administrators have been notified.")
        except:
            pass

# ==========================================
# MAIN APPLICATION BUILDER
# ==========================================
def main():
    application = ApplicationBuilder().token(BOT_TOKEN).build()

    application.add_handler(TypeHandler(Update, track_user_middleware), group=-1)

    reg_conv_handler = ConversationHandler(
        entry_points=[
            CommandHandler("register", register_start),
            CallbackQueryHandler(register_start, pattern="^cmd_register$")
        ],
        states={
            REGISTER_NAME: [MessageHandler(filters.TEXT & ~filters.COMMAND, register_name)],
            REGISTER_AGE: [MessageHandler(filters.TEXT & ~filters.COMMAND, register_age)],
            REGISTER_GENDER: [MessageHandler(filters.TEXT & ~filters.COMMAND, register_gender)],
            REGISTER_LOCATION: [MessageHandler(filters.TEXT & ~filters.COMMAND, register_location)],
            REGISTER_BIO: [MessageHandler(filters.TEXT & ~filters.COMMAND, register_bio)],
            REGISTER_PHOTO: [
                MessageHandler(filters.PHOTO, register_photo),
                CommandHandler("skip", register_skip_photo)
            ],
            REGISTER_CONFIRM: [CallbackQueryHandler(register_confirm_callback, pattern="^reg_")],
        },
        fallbacks=[CommandHandler("cancel", cancel_conversation)]
    )

    feedback_conv_handler = ConversationHandler(
        entry_points=[CommandHandler("feedback", feedback_start)],
        states={
            FEEDBACK_STATE: [MessageHandler(filters.TEXT & ~filters.COMMAND, feedback_receive)]
        },
        fallbacks=[CommandHandler("cancel", cancel_conversation)]
    )

    admin_broadcast_handler = ConversationHandler(
        entry_points=[CallbackQueryHandler(admin_broadcast_init, pattern="^admin_broadcast_init$"), CommandHandler("broadcast", admin_broadcast_init)],
        states={
            ADMIN_BROADCAST: [MessageHandler(filters.ALL & ~filters.COMMAND, admin_broadcast_send)]
        },
        fallbacks=[CommandHandler("cancel", cancel_conversation)]
    )

    application.add_handler(reg_conv_handler)
    application.add_handler(feedback_conv_handler)
    application.add_handler(admin_broadcast_handler)

    application.add_handler(CommandHandler("start", start_command))
    application.add_handler(CommandHandler("help", help_command))
    application.add_handler(CommandHandler("profile", view_profile))
    application.add_handler(CommandHandler("admin", admin_panel))

    application.add_handler(CallbackQueryHandler(admin_stats, pattern="^admin_stats$"))
    application.add_handler(CallbackQueryHandler(callback_router))

    application.add_handler(InlineQueryHandler(inline_query_handler))

    application.add_handler(MessageHandler(filters.PHOTO, handle_photo))
    application.add_handler(MessageHandler(filters.VOICE, handle_voice))
    application.add_handler(MessageHandler(filters.Document.ALL, handle_document))
    application.add_handler(MessageHandler(filters.COMMAND, unknown_command))

    application.add_error_handler(error_handler)

    logger.info("Starting MegaBot...")
    application.run_polling(allowed_updates=Update.ALL_TYPES)

if __name__ == "__main__":
    main()

